{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    n = len(nodes)
    if n == 0:
        raise ValueError("No nodes provided")
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core_distance for node {node}")
    if len(distances) == 0 and n > 1:
        raise ValueError("No distances provided for a multi-node graph")

    # Compute mutual reachability edges with canonicalized endpoints
    mr_edges = []
    for edge in distances:
        u, v, d = edge[0], edge[1], edge[2]
        if u not in core_distance:
            raise ValueError(f"Node {u} in distances not in core_distance")
        if v not in core_distance:
            raise ValueError(f"Node {v} in distances not in core_distance")
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize: lexicographic order
        if u > v:
            u, v = v, u
        mr_edges.append((mr, u, v))

    # Sort by mutual reachability, then by first endpoint, then by second endpoint
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
